import json,sys
from pathlib import Path

def ext_id(o):
    for r in o.get("external_references",[]):
        if r.get("source_name")=="mitre-attack": return r.get("external_id")
    return None

def load(path):
    b=json.loads(Path(path).read_text(encoding="utf-8"))
    objs=b.get("objects",[])
    by_id={o.get("id"):o for o in objs if o.get("id")}
    by_attack={ext_id(o):o for o in objs if ext_id(o)}
    return b,objs,by_id,by_attack

def tactics(obj,objs):
    phases={p.get("phase_name") for p in obj.get("kill_chain_phases",[]) if p.get("kill_chain_name")=="mitre-attack"}
    names=[]
    for t in objs:
        if t.get("type")=="x-mitre-tactic" and t.get("x_mitre_shortname") in phases: names.append(t.get("name"))
    return sorted(set(names or phases))

def main():
    if len(sys.argv)!=5: raise SystemExit("usage: python workbench.py enterprise-attack.json observations.json report.json layer.json")
    attack,obs,report,layer=sys.argv[1:]
    bundle,objs,by_id,by_attack=load(attack)
    observations=json.loads(Path(obs).read_text(encoding="utf-8"))
    rows=[]; seen=set()
    for x in observations:
        t=by_attack.get(x.get("attack_id"))
        if not t or t.get("type")!="attack-pattern":
            rows.append({**x,"resolution":"unresolved"}); continue
        row={**x,"resolution":"resolved","technique_name":t.get("name"),"tactics":tactics(t,objs),"stix_id":t.get("id")}
        rows.append(row); seen.add(x.get("attack_id"))
    out={"dataset_marker":bundle.get("id") or bundle.get("spec_version"),"resolved_count":sum(r["resolution"]=="resolved" for r in rows),"unresolved_count":sum(r["resolution"]=="unresolved" for r in rows),"observations":rows}
    Path(report).write_text(json.dumps(out,indent=2),encoding="utf-8")
    layer_obj={"name":"ATT&CK Evidence Layer","domain":"enterprise-attack","versions":{"attack":str(out["dataset_marker"])},"techniques":[{"techniqueID":i,"comment":"mapped from observations"} for i in sorted(seen)]}
    Path(layer).write_text(json.dumps(layer_obj,indent=2),encoding="utf-8")
    print("Resolved:",out["resolved_count"],"Unresolved:",out["unresolved_count"])

if __name__=="__main__": main()
